mapper.select:
SELECT allocation.sales_user_id AS owner_id, allocation.dept_id,
    COALESCE(SUM(CASE WHEN fact.baseline_flag = 0 THEN allocation.allocated_amount ELSE 0 END), 0) AS received_amount,
    COALESCE(SUM(CASE WHEN fact.baseline_flag = 1 THEN allocation.allocated_amount ELSE 0 END), 0) AS baseline_amount
FROM crm_deal_event fact JOIN crm_deal_allocation allocation
    ON allocation.event_id = fact.event_id AND allocation.tenant_id = fact.tenant_id
WHERE fact.tenant_id = #{scope.tenantId} AND fact.event_type = 'RECEIPT' AND fact.biz_type = 'RECEIVABLE'
    AND fact.currency = #{currency} AND fact.occurred_time >= #{start} AND fact.occurred_time <= #{end}

    AND (1 = 0
        OR allocation.sales_user_id = #{scope.userId}
        OR allocation.dept_id IN
            #{departmentId}
        )

AND allocation.sales_user_idAND allocation.dept_id
IN #{targetId}
GROUP BY allocation.sales_user_id, allocation.dept_id

SELECT receivable.owner_id, customer.dept_id, COALESCE(SUM(receivable.received_amount), 0) AS received_amount,
    0 AS baseline_amount
FROM crm_receivable receivable
LEFT JOIN crm_customer customer ON customer.customer_id = receivable.customer_id
    AND customer.tenant_id = receivable.tenant_id AND customer.deleted = 0
LEFT JOIN oa_contract contract ON contract.contract_id = receivable.contract_id AND contract.tenant_id = receivable.tenant_id
WHERE receivable.tenant_id = #{scope.tenantId} AND receivable.deleted = 0
    AND receivable.received_date >= #{start} AND receivable.received_date <= #{end}
    AND CASE WHEN receivable.contract_id IS NULL THEN 'CNY' ELSE contract.currency END = #{currency}

    AND (1 = 0
        OR receivable.owner_id = #{scope.userId}
        OR customer.dept_id IN
            #{departmentId}
        )

AND receivable.owner_idAND customer.dept_id
IN #{targetId}
GROUP BY receivable.owner_id, customer.dept_id
